const STAGES = ['待投递', '已投递', '面试中', '已结束'];
const STAGE_SET = new Set(STAGES);

const el = (sel, root = document) => root.querySelector(sel);
const els = (sel, root = document) => Array.from(root.querySelectorAll(sel));

const listEl = el('[data-role="list"]');
const emptyEl = el('[data-role="empty"]');
const errorEl = el('[data-role="error"]');
const formMask = el('[data-role="form-mask"]');
const formEl = el('[data-role="form"]');
const formTitleEl = el('[data-role="form-title"]');
const formErrorEl = el('[data-role="form-error"]');
const confirmMask = el('[data-role="confirm-mask"]');
const confirmTextEl = el('[data-role="confirm-text"]');

const inputCompany = el('#f-company');
const inputPosition = el('#f-position');
const inputDate = el('#f-date');
const inputStage = el('#f-stage');
const inputNote = el('#f-note');

let records = [];
let filter = 'all';
let editingId = null;
let pendingDeleteId = null;
let lastFocused = null;

function normalizeStage(value) {
  return STAGE_SET.has(value) ? value : '待投递';
}

function normalizeRecord(raw) {
  const src = raw && typeof raw === 'object' ? raw : {};
  const rec = Object.assign({}, src);
  rec.id = typeof src.id === 'string' && src.id ? src.id : makeId();
  rec.company = typeof src.company === 'string' ? src.company : '';
  rec.position = typeof src.position === 'string' ? src.position : '';
  rec.applyDate = typeof src.applyDate === 'string' ? src.applyDate : '';
  rec.stage = normalizeStage(src.stage);
  rec.note = typeof src.note === 'string' ? src.note : '';
  rec.createdAt = typeof src.createdAt === 'number' ? src.createdAt : Date.now();
  rec.updatedAt = typeof src.updatedAt === 'number' ? src.updatedAt : rec.createdAt;
  return rec;
}

function makeId() {
  return 'r-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
}

function todayStr() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return d.getFullYear() + '-' + m + '-' + day;
}

function showError(msg) {
  if (msg) {
    errorEl.textContent = msg;
    errorEl.hidden = false;
  } else {
    errorEl.textContent = '';
    errorEl.hidden = true;
  }
}

async function persist(nextRecords) {
  const state = await appStore.getState();
  const base = state && typeof state === 'object' ? state : {};
  const next = Object.assign({}, base, { records: nextRecords });
  await appStore.setState(next);
}

function countByStage() {
  const counts = { all: records.length };
  STAGES.forEach((s) => { counts[s] = 0; });
  records.forEach((r) => {
    const s = normalizeStage(r.stage);
    counts[s] = (counts[s] || 0) + 1;
  });
  return counts;
}

function renderStats() {
  const counts = countByStage();
  els('[data-stat-num]').forEach((node) => {
    const key = node.getAttribute('data-stat-num');
    node.textContent = String(counts[key] || 0);
  });
  els('[data-stat]').forEach((btn) => {
    const key = btn.getAttribute('data-stat');
    btn.classList.toggle('is-active', filter === key);
  });
  els('[data-filter]').forEach((btn) => {
    const key = btn.getAttribute('data-filter');
    btn.classList.toggle('is-active', filter === key);
  });
}

function buildRecordNode(rec) {
  const li = document.createElement('li');
  li.className = 'record';
  li.setAttribute('data-stage', rec.stage);
  li.setAttribute('data-id', rec.id);

  const head = document.createElement('div');
  head.className = 'record-head';

  const info = document.createElement('div');
  const company = document.createElement('h3');
  company.className = 'record-company';
  company.textContent = rec.company || '（未填写公司）';
  const position = document.createElement('p');
  position.className = 'record-position';
  position.textContent = rec.position || '（未填写岗位）';
  info.appendChild(company);
  info.appendChild(position);

  const badge = document.createElement('span');
  badge.className = 'badge';
  badge.setAttribute('data-stage', rec.stage);
  badge.textContent = rec.stage;

  head.appendChild(info);
  head.appendChild(badge);
  li.appendChild(head);

  const meta = document.createElement('p');
  meta.className = 'record-meta';
  meta.textContent = '投递日期：' + (rec.applyDate || '未填写');
  li.appendChild(meta);

  if (rec.note) {
    const note = document.createElement('p');
    note.className = 'record-note';
    note.textContent = rec.note;
    li.appendChild(note);
  }

  const actions = document.createElement('div');
  actions.className = 'record-actions';

  const editBtn = document.createElement('button');
  editBtn.type = 'button';
  editBtn.className = 'btn btn-ghost btn-mini';
  editBtn.textContent = '编辑';
  editBtn.addEventListener('click', () => openEdit(rec.id));

  const delBtn = document.createElement('button');
  delBtn.type = 'button';
  delBtn.className = 'btn btn-danger btn-mini';
  delBtn.textContent = '删除';
  delBtn.addEventListener('click', () => openDelete(rec.id));

  actions.appendChild(editBtn);
  actions.appendChild(delBtn);
  li.appendChild(actions);

  return li;
}

function renderList() {
  const visible = filter === 'all'
    ? records.slice()
    : records.filter((r) => normalizeStage(r.stage) === filter);

  visible.sort((a, b) => {
    const da = a.applyDate || '';
    const db = b.applyDate || '';
    if (da !== db) return db.localeCompare(da);
    return (b.createdAt || 0) - (a.createdAt || 0);
  });

  listEl.textContent = '';
  visible.forEach((rec) => listEl.appendChild(buildRecordNode(rec)));

  if (records.length === 0) {
    emptyEl.textContent = '还没有投递记录，点击「新增投递」开始记录吧。';
    emptyEl.hidden = false;
  } else if (visible.length === 0) {
    emptyEl.textContent = '当前筛选「' + filter + '」下暂无记录。';
    emptyEl.hidden = false;
  } else {
    emptyEl.hidden = true;
  }
}

function render() {
  renderStats();
  renderList();
}

function openForm(rec) {
  editingId = rec ? rec.id : null;
  formTitleEl.textContent = rec ? '编辑投递记录' : '新增投递';
  inputCompany.value = rec ? rec.company : '';
  inputPosition.value = rec ? rec.position : '';
  inputDate.value = rec ? rec.applyDate : todayStr();
  inputStage.value = rec ? normalizeStage(rec.stage) : '待投递';
  inputNote.value = rec ? rec.note : '';
  formErrorEl.textContent = '';
  formErrorEl.hidden = true;
  lastFocused = document.activeElement;
  formMask.hidden = false;
  inputCompany.focus();
}

function closeForm() {
  formMask.hidden = true;
  editingId = null;
  if (lastFocused && typeof lastFocused.focus === 'function') lastFocused.focus();
}

function openEdit(id) {
  const rec = records.find((r) => r.id === id);
  if (!rec) return;
  openForm(rec);
}

function openDelete(id) {
  const rec = records.find((r) => r.id === id);
  if (!rec) return;
  pendingDeleteId = id;
  confirmTextEl.textContent = '确定要删除「' + (rec.company || '未填写公司') + ' · ' + (rec.position || '未填写岗位') + '」这条记录吗？删除后无法恢复。';
  lastFocused = document.activeElement;
  confirmMask.hidden = false;
  const okBtn = el('[data-action="confirm-delete"]');
  if (okBtn) okBtn.focus();
}

function closeDelete() {
  confirmMask.hidden = true;
  pendingDeleteId = null;
  if (lastFocused && typeof lastFocused.focus === 'function') lastFocused.focus();
}

async function handleSubmit(event) {
  event.preventDefault();
  const company = inputCompany.value.trim();
  const position = inputPosition.value.trim();
  const applyDate = inputDate.value;
  const stage = normalizeStage(inputStage.value);
  const note = inputNote.value.trim();

  if (!company) {
    formErrorEl.textContent = '请填写公司名称。';
    formErrorEl.hidden = false;
    inputCompany.focus();
    return;
  }
  if (!position) {
    formErrorEl.textContent = '请填写岗位名称。';
    formErrorEl.hidden = false;
    inputPosition.focus();
    return;
  }

  const now = Date.now();
  let next;
  if (editingId) {
    next = records.map((r) => {
      if (r.id !== editingId) return r;
      return Object.assign({}, r, {
        company: company,
        position: position,
        applyDate: applyDate,
        stage: stage,
        note: note,
        updatedAt: now
      });
    });
  } else {
    const rec = normalizeRecord({
      id: makeId(),
      company: company,
      position: position,
      applyDate: applyDate,
      stage: stage,
      note: note,
      createdAt: now,
      updatedAt: now
    });
    next = records.concat([rec]);
  }

  try {
    await persist(next);
  } catch (err) {
    formErrorEl.textContent = '保存失败，请重试。你的输入已保留。';
    formErrorEl.hidden = false;
    return;
  }

  records = next;
  closeForm();
  showError('');
  render();
}

async function handleConfirmDelete() {
  if (!pendingDeleteId) {
    closeDelete();
    return;
  }
  const id = pendingDeleteId;
  const next = records.filter((r) => r.id !== id);
  try {
    await persist(next);
  } catch (err) {
    closeDelete();
    showError('删除失败，请重试。');
    return;
  }
  records = next;
  closeDelete();
  showError('');
  render();
}

async function init() {
  let state = null;
  try {
    state = await appStore.getState();
  } catch (err) {
    state = null;
  }

  const base = state && typeof state === 'object' ? state : {};
  const rawList = Array.isArray(base.records) ? base.records : null;

  if (rawList === null) {
    // 业务键不存在：首次打开，从空数据开始，不预置示例记录
    records = [];
    try {
      await persist(records);
    } catch (err) {
      showError('初始化数据失败，当前修改可能无法保存。');
    }
  } else {
    records = rawList.map(normalizeRecord);
  }

  render();

  els('[data-filter]').forEach((btn) => {
    btn.addEventListener('click', () => {
      filter = btn.getAttribute('data-filter') || 'all';
      render();
    });
  });

  els('[data-stat]').forEach((btn) => {
    btn.addEventListener('click', () => {
      filter = btn.getAttribute('data-stat') || 'all';
      render();
    });
  });

  el('[data-action="open-create"]').addEventListener('click', () => openForm(null));
  el('[data-action="cancel-form"]').addEventListener('click', closeForm);
  el('[data-action="cancel-delete"]').addEventListener('click', closeDelete);
  el('[data-action="confirm-delete"]').addEventListener('click', handleConfirmDelete);

  formEl.addEventListener('submit', handleSubmit);

  formMask.addEventListener('click', (e) => {
    if (e.target === formMask) closeForm();
  });
  confirmMask.addEventListener('click', (e) => {
    if (e.target === confirmMask) closeDelete();
  });

  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    if (!confirmMask.hidden) {
      closeDelete();
    } else if (!formMask.hidden) {
      closeForm();
    }
  });
}

await init();

