:root {
  --bg: #0b1220;
  --bg-soft: #111c30;
  --panel: #16233a;
  --panel-2: #1c2b45;
  --line: #2a3b58;
  --line-soft: #223350;
  --ink: #e8eefb;
  --ink-soft: #9fb0cc;
  --blue-400: #60a5fa;
  --blue-500: #3b82f6;
  --blue-600: #2563eb;
  --blue-700: #1d4ed8;
  --blue-900: #0f2f66;
  --danger: #ef4444;
  --danger-soft: #3b1a1f;
  --radius: 14px;
  --shadow: 0 10px 26px rgba(0, 0, 0, 0.45);
}

* { box-sizing: border-box; }

.wrap {
  max-width: 720px;
  margin: 0 auto;
  padding: 16px 14px 40px;
  color: var(--ink);
  font-size: 15px;
  line-height: 1.5;
}

.topbar {
  background: linear-gradient(135deg, #142a52, #1d4ed8);
  color: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px 16px;
  box-shadow: var(--shadow);
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: #c7d7f5;
}

.stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  margin-top: 14px;
}

.stat-card {
  appearance: none;
  border: 1px solid var(--line);
  background: var(--panel);
  border-radius: 12px;
  padding: 10px 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  cursor: pointer;
  font-family: inherit;
  color: var(--ink-soft);
  transition: border-color .15s, background .15s, transform .1s;
}

.stat-card:active { transform: scale(0.97); }

.stat-card.is-active {
  border-color: var(--blue-500);
  background: var(--panel-2);
  box-shadow: inset 0 0 0 1px rgba(59, 130, 246, 0.35);
}

.stat-num {
  font-size: 18px;
  font-weight: 700;
  color: var(--blue-400);
}

.stat-label {
  font-size: 11px;
  white-space: nowrap;
}

.search-area { margin-top: 16px; }

.search-label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-soft);
  margin-bottom: 6px;
}

.search-row {
  display: flex;
  gap: 8px;
  align-items: center;
}

.search-row input {
  flex: 1 1 auto;
  min-width: 0;
  font-family: inherit;
  font-size: 15px;
  color: var(--ink);
  background: var(--bg-soft);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 9px 11px;
  outline: none;
  transition: border-color .15s, box-shadow .15s;
}

.search-row input::placeholder { color: #6f819e; }

.search-row input:focus {
  border-color: var(--blue-500);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.22);
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
}

.filter-group {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  flex: 1 1 auto;
}

.chip {
  appearance: none;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink-soft);
  border-radius: 999px;
  padding: 6px 12px;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  transition: background .15s, color .15s, border-color .15s;
}

.chip:hover { border-color: var(--blue-500); }

.chip.is-active {
  background: var(--blue-600);
  border-color: var(--blue-600);
  color: #fff;
  font-weight: 600;
}

.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 9px 16px;
  font-size: 14px;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s, border-color .15s, color .15s, transform .1s;
}

.btn:active { transform: scale(0.98); }

.btn-primary {
  background: var(--blue-600);
  color: #fff;
}

.btn-primary:hover { background: var(--blue-700); }

.btn-ghost {
  background: var(--panel);
  border-color: var(--line);
  color: var(--ink-soft);
}

.btn-ghost:hover { background: var(--panel-2); color: var(--ink); }

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.btn-danger:hover { background: #b91c1c; }

.btn-mini {
  padding: 6px 12px;
  font-size: 13px;
  border-radius: 8px;
}

.result-hint {
  margin: 12px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.error {
  margin: 12px 0 0;
  padding: 10px 12px;
  background: var(--danger-soft);
  color: #fca5a5;
  border: 1px solid #7f1d1d;
  border-radius: 10px;
  font-size: 13px;
}

.list-area { margin-top: 16px; }

.empty {
  margin: 24px 0;
  text-align: center;
  color: var(--ink-soft);
  font-size: 14px;
  background: var(--panel);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
  padding: 28px 16px;
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record {
  background: var(--panel);
  border: 1px solid var(--line);
  border-left: 4px solid var(--blue-500);
  border-radius: var(--radius);
  padding: 12px 14px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
}

.record[data-stage="待投递"] { border-left-color: #94a3b8; }
.record[data-stage="已投递"] { border-left-color: var(--blue-500); }
.record[data-stage="面试中"] { border-left-color: #f59e0b; }
.record[data-stage="已结束"] { border-left-color: #10b981; }

.record-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: #dbeafe;
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
  word-break: break-word;
}

.badge {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 999px;
  background: rgba(59, 130, 246, 0.18);
  color: var(--blue-400);
  white-space: nowrap;
}

.badge[data-stage="待投递"] { background: rgba(148, 163, 184, 0.18); color: #cbd5e1; }
.badge[data-stage="已投递"] { background: rgba(59, 130, 246, 0.18); color: var(--blue-400); }
.badge[data-stage="面试中"] { background: rgba(245, 158, 11, 0.18); color: #fbbf24; }
.badge[data-stage="已结束"] { background: rgba(16, 185, 129, 0.18); color: #34d399; }

.record-meta {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--ink-soft);
}

.record-note {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--ink);
  background: var(--bg-soft);
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  margin-top: 10px;
  justify-content: flex-end;
}

.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(3, 8, 18, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 50;
}

.modal-mask[hidden] { display: none; }

.modal {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 18px 16px;
  width: 100%;
  max-width: 460px;
  max-height: 88vh;
  overflow-y: auto;
  box-shadow: var(--shadow);
}

.modal-sm { max-width: 360px; }

.modal-title {
  margin: 0 0 14px;
  font-size: 17px;
  color: #dbeafe;
}

.confirm-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--ink-soft);
  word-break: break-word;
}

.form { display: flex; flex-direction: column; gap: 12px; }

.field { display: flex; flex-direction: column; gap: 5px; }

.field label {
  font-size: 13px;
  font-weight: 600;
  color: #c7d7f5;
}

.req { color: #f87171; }

.field input,
.field select,
.field textarea {
  width: 100%;
  font-family: inherit;
  font-size: 15px;
  color: var(--ink);
  background: var(--bg-soft);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 9px 11px;
  outline: none;
  transition: border-color .15s, box-shadow .15s;
}

.field input::placeholder,
.field textarea::placeholder { color: #6f819e; }

.field textarea { resize: vertical; }

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--blue-500);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.22);
}

.form-error {
  margin: 0;
  font-size: 13px;
  color: #f87171;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 4px;
}

@media (max-width: 420px) {
  .stats { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .toolbar { flex-direction: column; align-items: stretch; }
  .toolbar .btn-primary { width: 100%; }
  .record-actions { justify-content: stretch; }
  .record-actions .btn { flex: 1; }
}
